// Calculate total daily income from all sources
let totalIncome = 0;
let sources = [];

// Process each affiliate source
for (const item of $input.all()) {
  if (item.json.daily_commissions) {
    totalIncome += parseFloat(item.json.daily_commissions);
    sources.push({
      source: item.json.source || 'Unknown',
      amount: parseFloat(item.json.daily_commissions),
      conversions: item.json.conversions || 0
    });
  }
}

// Calculate progress toward $500 goal
const dailyTarget = 500;
const progressPercentage = (totalIncome / dailyTarget) * 100;
const remainingAmount = Math.max(0, dailyTarget - totalIncome);

// Determine status and next actions
let status = 'on_track';
let nextActions = [];

if (totalIncome >= dailyTarget) {
  status = 'target_exceeded';
  nextActions = ['Scale successful campaigns', 'Test new affiliate programs', 'Increase daily target'];
} else if (progressPercentage >= 75) {
  status = 'on_track';
  nextActions = ['Continue current strategy', 'Optimize top performers', 'Prepare evening push'];
} else if (progressPercentage >= 50) {
  status = 'needs_attention';
  nextActions = ['Boost underperforming campaigns', 'Create urgent content', 'Increase social media activity'];
} else {
  status = 'critical';
  nextActions = ['Emergency campaign activation', 'Reach out to warm leads', 'Create flash promotions'];
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    total_daily_income: totalIncome,
    daily_target: dailyTarget,
    progress_percentage: Math.round(progressPercentage * 100) / 100,
    remaining_amount: remainingAmount,
    status: status,
    sources: sources,
    next_actions: nextActions,
    hour_of_day: new Date().getHours()
  }
}];

